/**
 * 段落级本地化组件（2026-11-12，随「批量扩页」落地）
 *
 * 为什么不逐节点替换文本：页面里有大量 `<p>Whaleal <a>…</a> builds …</p>` 这类
 * **被内联元素切碎的句子**。逐片段翻译会把语序翻烂（"Whaleal"、". Our flagship
 * app," 各自成条），而且不报错、构建全绿，只有人眼读译文才发现。
 *
 * 本组件的口径：
 * - 页面结构**完全不动**，只在含文本的最外层元素外裹一层 `<T id="…">`（由
 *   `scripts/` 之外的一次性改造脚本插入，本文件不依赖 AST 工具）。
 * - 字典值是**整个段落的模板**：内联元素 / 动态表达式统一写成 `{0}` `{1}` …
 *   占位符，译文可以按目标语言重排占位符顺序（德语的动词后置等），运行时把
 *   原始 React 节点插回对应位置 ⇒ 链接、className、事件处理器一个都不丢。
 * - 英文页直接返回原 children，**零行为变化**；其它语言读
 *   `dictionaries/innerPages.js` 对应块，缺条目回落英文（护栏会阻断发布）。
 *
 * 🔴 SSR 安全：`useI18n()` 的 locale 来自 `Layout` 传入的 `pageContext.locale`
 *    （`gatsby-node.onCreatePage` 注入），不是 `useLocation()` 的推演。
 *    页面 JSX 作为 `<Layout>` 的 children 渲染，处于 `I18nProvider` **之内**，
 *    因此这里能拿到正确语言；SSR 与客户端 hydrate 用的是同一个值。
 *
 * 🔴 占位符编号与改造脚本的抽取规则必须一致：
 *    「字符串 / 纯字符串表达式」= 文本段（不占槽）；其余节点按出现顺序占槽。
 *    运行时用**原始 children 数组**，刻意不用 `React.Children.toArray()` ——
 *    后者会把 `{items.map(...)}` 展开成 N 个元素，导致槽位编号错位。
 *
 * @author 恒哥
 */
import React from 'react';
import { useI18n } from './index';
import innerPages from './dictionaries/innerPages';

const SLOT = /\{(\d+)\}/g;

/** 取当前语言的段落模板字典（供属性文案等标量场景使用）。 */
export function useCopyText() {
  const { locale } = useI18n();
  return React.useMemo(() => {
    const dict = innerPages[locale] || innerPages.en;
    return (key) => dict[key] || innerPages.en[key] || key;
  }, [locale]);
}

/**
 * @param {{ id: string, children: React.ReactNode }} props
 */
export default function LocalizedText({ id, children }) {
  const { locale } = useI18n();
  const template = (innerPages[locale] || {})[id];
  if (locale === 'en' || !template) return <>{children}</>;

  // 与抽取脚本同规则：字符串（JSXText / 字符串字面量表达式）是文本段，其余占槽。
  const raw = Array.isArray(children) ? children : [children];
  const slots = raw.filter((child) => typeof child !== 'string');

  const nodes = [];
  let cursor = 0;
  let match;
  SLOT.lastIndex = 0;
  while ((match = SLOT.exec(template)) !== null) {
    if (match.index > cursor) nodes.push(template.slice(cursor, match.index));
    nodes.push(slots[Number(match[1])] ?? null);
    cursor = match.index + match[0].length;
  }
  if (cursor < template.length) nodes.push(template.slice(cursor));

  return (
    <>
      {nodes.map((node, i) => (
        // eslint-disable-next-line react/no-array-index-key
        <React.Fragment key={i}>{node}</React.Fragment>
      ))}
    </>
  );
}
